<?php
require_once __DIR__ . '/../config/database.php';
require_once __DIR__ . '/../includes/auth.php';
requireRole('admin');
$admin = currentUser(); $pageTitle = 'Pickup Requests | Eco-Loop';
$transitions = ['Pending'=>['Approved','Scheduled','Rejected','Cancelled'],'Approved'=>['Scheduled','Rejected','Cancelled'],'Scheduled'=>['Rejected','Cancelled'],'Collector Assigned'=>['On the Way','Collected'],'On the Way'=>['Collected'],'Collected'=>['Completed'],'Completed'=>[],'Cancelled'=>[],'Rejected'=>[]];
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    require_csrf(); $pickupId = filter_var($_POST['pickup_id'] ?? 0, FILTER_VALIDATE_INT) ?: 0; $newStatus = trim((string) ($_POST['status'] ?? '')); $reason = trim((string) ($_POST['reason'] ?? '')); $connection = db();
    try {
        if ($newStatus === 'Rejected' && ($reason === '' || mb_strlen($reason) > 1000)) throw new RuntimeException('Provide a rejection reason (up to 1,000 characters) so the customer knows what to correct.');
        $connection->begin_transaction();
        $lock=$connection->prepare('SELECT id,user_id,status,reference_number FROM pickup_requests WHERE id=? FOR UPDATE'); $lock->bind_param('i',$pickupId); $lock->execute(); $pickup=$lock->get_result()->fetch_assoc(); $lock->close();
        if (!$pickup || !in_array($newStatus,$transitions[$pickup['status']]??[],true)) throw new RuntimeException('That status change is not allowed.');
        $verification=null;
        if ($newStatus==='Completed') { $check=$connection->prepare('SELECT total_points FROM pickup_verifications WHERE pickup_request_id=? LIMIT 1 FOR UPDATE'); $check->bind_param('i',$pickupId); $check->execute(); $verification=$check->get_result()->fetch_assoc(); $check->close(); if(!$verification)throw new RuntimeException('Verify received e-waste before completing this pickup.'); }
        $update=$connection->prepare('UPDATE pickup_requests SET status=?, cancellation_reason=IF(?="Rejected",?,cancellation_reason) WHERE id=?'); $update->bind_param('sssi',$newStatus,$newStatus,$reason,$pickupId); $update->execute(); $update->close();
        $assignmentStatus=['Collector Assigned'=>'Assigned','On the Way'=>'On the Way','Collected'=>'Collected','Completed'=>'Completed'][$newStatus]??null;
        if($assignmentStatus!==null){$assignmentLookup=$connection->prepare('SELECT id FROM pickup_assignments WHERE pickup_request_id=? ORDER BY assigned_at DESC,id DESC LIMIT 1 FOR UPDATE');$assignmentLookup->bind_param('i',$pickupId);$assignmentLookup->execute();$assignmentRow=$assignmentLookup->get_result()->fetch_assoc();$assignmentLookup->close();if($assignmentRow){$assignmentUpdate=$connection->prepare('UPDATE pickup_assignments SET status=? WHERE id=?');$assignmentUpdate->bind_param('si',$assignmentStatus,$assignmentRow['id']);$assignmentUpdate->execute();$assignmentUpdate->close();}}
        $note=$newStatus==='Rejected'?'Rejected: '.$reason:'Status updated by an administrator.';
        createPickupStatusEntry($pickupId,$pickup['status'],$newStatus,(int)$admin['id'],$note);
        if($newStatus==='Completed') {
            $points=(int)$verification['total_points'];
            if($points>0){$type='earned';$note='Points for verified e-waste on completed pickup '.$pickup['reference_number'];$uid=(int)$pickup['user_id'];$aid=(int)$admin['id'];$award=$connection->prepare('INSERT INTO points_transactions (user_id,points,transaction_type,related_pickup_id,notes,created_by) VALUES (?,?,?,?,?,?)');$award->bind_param('iisisi',$uid,$points,$type,$pickupId,$note,$aid);$award->execute();$award->close();}
        }
        $message=$newStatus==='Rejected'?'Pickup '.$pickup['reference_number'].' was rejected: '.$reason:('Pickup '.$pickup['reference_number'].' is now '.$newStatus.($newStatus==='Completed'?' and '.$points.' points were awarded for verified items.':'.'));
        createNotification((int)$pickup['user_id'],$newStatus==='Completed'?'Pickup completed':'Pickup status updated',$message,$newStatus==='Rejected'?'warning':($newStatus==='Completed'?'success':'info'),$pickupId);
        logAdminAction((int)$admin['id'],'Pickup status changed','Pickup '.$pickup['reference_number'].': '.$pickup['status'].' → '.$newStatus.($reason!==''?' | Reason: '.$reason:''));
        $connection->commit(); setFlash('success',$newStatus==='Completed'?'Pickup completed and verified points awarded once.':'Pickup status updated.');
    } catch(RuntimeException $ex){$connection->rollback();setFlash('error',$ex->getMessage());} catch(Throwable $ex){$connection->rollback();error_log('EcoLoop admin pickup update failed: '.$ex->getMessage());setFlash('error','The pickup status could not be updated. Please try again.');}
    redirect('admin/pickups.php');
}
$search=trim((string)($_GET['search']??'')); $statusFilter=trim((string)($_GET['status']??'')); $page=max(1,filter_input(INPUT_GET,'page',FILTER_VALIDATE_INT)?:1); $limit=25; $offset=($page-1)*$limit; $like='%'.$search.'%';
$allowedStatuses=['Pending','Approved','Scheduled','Collector Assigned','On the Way','Collected','Completed','Cancelled','Rejected']; if(!in_array($statusFilter,$allowedStatuses,true))$statusFilter='';
$where='(?="" OR p.reference_number LIKE ? OR u.full_name LIKE ? OR u.email LIKE ? OR p.contact_number LIKE ?) AND (?="" OR p.status=?)';
$connection=db();$countStmt=$connection->prepare('SELECT COUNT(*) total FROM pickup_requests p JOIN users u ON u.id=p.user_id WHERE '.$where);$countStmt->bind_param('sssssss',$search,$like,$like,$like,$like,$statusFilter,$statusFilter);$countStmt->execute();$totalRows=(int)$countStmt->get_result()->fetch_assoc()['total'];$countStmt->close();$totalPages=max(1,(int)ceil($totalRows/$limit));$page=min($page,$totalPages);$offset=($page-1)*$limit;
$stmt=$connection->prepare('SELECT p.id,p.reference_number,p.user_id,p.service_type,p.service_fee,p.status,p.pickup_address,p.latitude,p.longitude,p.distance_km,p.preferred_date,p.preferred_time,p.created_at,p.contact_number,p.customer_name,p.description,u.full_name,u.email,(SELECT GROUP_CONCAT(CONCAT(i.item_category," × ",i.quantity) ORDER BY i.id SEPARATOR ", ") FROM pickup_items i WHERE i.pickup_request_id=p.id) items,(v.id IS NOT NULL) has_verification FROM pickup_requests p JOIN users u ON u.id=p.user_id LEFT JOIN pickup_verifications v ON v.pickup_request_id=p.id WHERE '.$where.' ORDER BY p.created_at DESC,p.id DESC LIMIT ? OFFSET ?');
$stmt->bind_param('sssssssii',$search,$like,$like,$like,$like,$statusFilter,$statusFilter,$limit,$offset);$stmt->execute();$pickups=$stmt->get_result()->fetch_all(MYSQLI_ASSOC);$stmt->close();
require __DIR__ . '/../includes/header.php';
?>
<div class="dashboard-shell"><?php require __DIR__ . '/../includes/navigation.php'; ?><main class="main-content">
<div class="page-header"><div><span class="eyebrow">Operations</span><h1>Pickup Requests</h1><p>Review customer details, location, declared items, and collection status.</p></div></div>
<section class="content-card"><form method="get" class="inline-form"><label>Search <input name="search" value="<?php echo e($search); ?>" placeholder="Request, customer, email, phone"></label><label>Status <select name="status"><option value="">All statuses</option><?php foreach($allowedStatuses as $status):?><option value="<?php echo e($status);?>" <?php echo $statusFilter===$status?'selected':'';?>><?php echo e($status==='Approved'?'Accepted':$status);?></option><?php endforeach;?></select></label><button class="btn btn-secondary">Filter</button></form></section>
<?php if($pickups):?><div class="workflow-card-grid"><?php foreach($pickups as $pickup):?><article class="pickup-card"><div class="pickup-card-header"><div><h3><?php echo e($pickup['reference_number']);?></h3><p><?php echo e($pickup['customer_name']?:$pickup['full_name']);?> · <?php echo e($pickup['email']);?></p></div><span class="status-pill"><?php echo e($pickup['status']==='Approved'?'Accepted':$pickup['status']);?></span></div>
<p><strong>Contact:</strong> <a href="tel:<?php echo e($pickup['contact_number']?:''); ?>"><?php echo e($pickup['contact_number']?:'Not provided');?></a></p><p><strong>Service:</strong> <?php echo e($pickup['service_type']==='priority'?'Priority Collection':'Convenience (Saver)');?> · <?php echo e(formatCurrency((float)$pickup['service_fee']));?></p><p><strong>Distance:</strong> <?php echo $pickup['distance_km']!==null?e(number_format((float)$pickup['distance_km'],2).' km estimate'):'Not available';?></p><p><strong>Declared items:</strong> <?php echo e($pickup['items']?:'Not specified');?></p><p><strong>Address:</strong> <?php echo e($pickup['pickup_address']);?></p><p><strong>Requested:</strong> <?php echo e($pickup['preferred_date']?:'As soon as available');?> <?php echo e($pickup['preferred_time']?substr($pickup['preferred_time'],0,5):'');?> · <?php echo e(date('M j, Y g:i A',strtotime($pickup['created_at'])));?></p>
<?php if($pickup['latitude']!==null&&$pickup['longitude']!==null):?><p><a target="_blank" rel="noopener" href="https://www.google.com/maps?q=<?php echo rawurlencode($pickup['latitude'].','.$pickup['longitude']);?>">Map pin: <?php echo e($pickup['latitude']);?>, <?php echo e($pickup['longitude']);?></a></p><?php else:?><p>No pickup map pin saved.</p><?php endif;?><?php if($pickup['description']):?><p><strong>Customer notes:</strong> <?php echo e($pickup['description']);?></p><?php endif;?>
<p><a class="btn btn-secondary" href="<?php echo e(APP_ROOT.'/admin/pickup-details.php?id='.(int)$pickup['id']);?>">View full details &amp; history</a></p>
<?php if($pickup['status']==='Collected'&&!$pickup['has_verification']):?><p><a class="btn btn-secondary" href="<?php echo e(APP_ROOT.'/admin/verify-pickup-items.php?id='.(int)$pickup['id']);?>">Verify received e-waste</a></p><?php elseif($pickup['status']==='Collected'):?><p class="muted-text">Verified items recorded. Completing awards the configured points once.</p><?php endif;?>
<?php $options=$transitions[$pickup['status']]??[];if($pickup['status']==='Collected'&&!$pickup['has_verification'])$options=[];?><?php if($options):?><form method="post" class="pickup-card-actions"><?php echo csrf_field();?><input type="hidden" name="pickup_id" value="<?php echo(int)$pickup['id'];?>"><label for="status-<?php echo(int)$pickup['id'];?>">Change status</label><select id="status-<?php echo(int)$pickup['id'];?>" name="status" required><?php foreach($options as $option):?><option value="<?php echo e($option);?>"><?php echo e($option==='Approved'?'Accept request':$option);?></option><?php endforeach;?></select><textarea name="reason" maxlength="1000" placeholder="Required when rejecting; optional otherwise"></textarea><button class="btn btn-primary" type="submit">Save status</button></form><?php endif;?></article><?php endforeach;?></div><?php else:?><div class="content-card empty-state"><h2>No matching pickup requests</h2><p>New requests appear here when customers submit them.</p></div><?php endif;?>
<div class="modal-actions"><?php if($page>1):?><a class="btn btn-outline" href="?search=<?php echo rawurlencode($search);?>&amp;status=<?php echo rawurlencode($statusFilter);?>&amp;page=<?php echo $page-1;?>">Previous</a><?php endif;?><span>Page <?php echo $page;?> of <?php echo $totalPages;?></span><?php if($page<$totalPages):?><a class="btn btn-outline" href="?search=<?php echo rawurlencode($search);?>&amp;status=<?php echo rawurlencode($statusFilter);?>&amp;page=<?php echo $page+1;?>">Next</a><?php endif;?></div>
</main></div><?php require __DIR__ . '/../includes/footer.php'; ?>
